         var body: some View {
             NavigationView {
                 VStack {
                     Text("Home")
                     NavigationLink(destination: DetailView()) {
                         Text("Go to Detail")
                     }
                 }
             }
         }
     }

     struct DetailView: View {
         var body: some View {
             Text("This is the detail view")
         }
     }
     ```

8. **Testing and Debugging:**
   - Use the Xcode simulator to test your app on different devices and screen sizes.
